perm = (0, 1, 4, 3, 5, 2)
seen = {}
n = len(perm)
for i in range(n):
    for j in range(i+1, n):
        dr = perm[j] - perm[i]
        dc = j - i
        print(f"({i},{j}): dr={dr}, dc={dc}")
        if (dr, dc) in seen:
            print(f"DUPLICATE: ({dr}, {dc}) already seen from {seen[(dr, dc)]}")
        seen[(dr, dc)] = (i, j)

print(f"\nTotal unique vectors: {len(seen)}")
print(f"Expected: {n*(n-1)//2}")
